    let diff = git2::Diff::from_buffer(patch).unwrap();
    let calls = Cell::new(0);
    let mut opts = options(&calls);
    repo.apply(&diff, git2::ApplyLocation::Index, Some(&mut opts)).unwrap();
    assert_eq!(calls.get(), 1);
}
